    const STORAGE_KEY = "dev_roadmaps_user_progress_v1";

    let activeRoadmapId = "springboot";
    let activeCategory = "All";
    let allExpanded = false;
    let userProgress = {};

    // Load progress from localStorage
    function loadProgress() {
      try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
          userProgress = JSON.parse(saved);
        }
      } catch (e) {
        console.error("Could not load from localStorage:", e);
      }
    }

    // Save progress to localStorage
    function saveProgress() {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(userProgress));
      } catch (e) {
        console.error("Could not save to localStorage:", e);
      }
    }

    // Switch active roadmap
    function switchRoadmap(id) {
      activeRoadmapId = id;
      renderTabs();
      renderActiveRoadmap();
      window.scrollTo({ top: document.querySelector('.roadmap-panel').offsetTop - 90, behavior: 'smooth' });
    }

    // Filter by Category
    function filterCategory(cat, btn) {
      activeCategory = cat;
      document.querySelectorAll('.cat-chip').forEach(el => el.classList.remove('active'));
      if (btn) btn.classList.add('active');
      
      const keys = Object.keys(ROADMAPS_DATA);
      const matches = keys.filter(k => cat === 'All' || ROADMAPS_DATA[k].category === cat);
      if (matches.length > 0 && !matches.includes(activeRoadmapId)) {
        activeRoadmapId = matches[0];
      }
      renderTabs();
      renderActiveRoadmap();
    }

    // Render Navigation Tabs
    function renderTabs() {
      const nav = document.getElementById("roadmapsNavList");
      nav.innerHTML = "";

      Object.values(ROADMAPS_DATA).forEach(roadmap => {
        if (activeCategory !== 'All' && roadmap.category !== activeCategory) return;

        const btn = document.createElement("button");
        btn.className = `roadmap-tab-btn ${roadmap.id === activeRoadmapId ? 'active' : ''}`;
        btn.onclick = () => switchRoadmap(roadmap.id);

        let total = 0;
        let checked = 0;
        roadmap.phases.forEach(p => {
          p.topics.forEach((t, idx) => {
            total++;
            const itemKey = `${roadmap.id}_${p.id}_${idx}`;
            if (userProgress[itemKey]) checked++;
          });
        });
        const pct = total > 0 ? Math.round((checked / total) * 100) : 0;

        btn.innerHTML = `
          <div class="tab-indicator"></div>
          <span>${roadmap.title.split(' · ')[0]}</span>
          <span style="font-size: 0.72rem; opacity: 0.7; margin-left: 0.2rem;">${pct}%</span>
        `;
        nav.appendChild(btn);
      });
    }

    // Render Active Roadmap Content
    function renderActiveRoadmap() {
      const roadmap = ROADMAPS_DATA[activeRoadmapId];
      if (!roadmap) return;

      document.getElementById("activeRoadmapTitle").textContent = roadmap.title;
      document.getElementById("activeRoadmapDesc").textContent = roadmap.description;
      document.getElementById("activeCategoryTag").textContent = roadmap.category;
      document.getElementById("activeTechTag").textContent = roadmap.tag || "Full Path";
      document.getElementById("phasesCountText").textContent = `${roadmap.phases.length} Phases`;

      renderPhases();
      updateRoadmapProgress();
    }

    // Render Phases and Topic Checklists
    function renderPhases() {
      const roadmap = ROADMAPS_DATA[activeRoadmapId];
      const container = document.getElementById("phaseListContainer");
      container.innerHTML = "";

      roadmap.phases.forEach((phase, phaseIndex) => {
        const phaseCard = document.createElement("div");
        phaseCard.className = `phase-card ${allExpanded || phaseIndex === 0 ? 'open' : ''}`;
        phaseCard.id = `phase_card_${phase.id}`;

        let phaseTotal = phase.topics.length;
        let phaseChecked = 0;
        phase.topics.forEach((_, tIdx) => {
          const itemKey = `${roadmap.id}_${phase.id}_${tIdx}`;
          if (userProgress[itemKey]) phaseChecked++;
        });

        if (phaseChecked === phaseTotal && phaseTotal > 0) {
          phaseCard.classList.add("all-completed");
        }

        // Card Header
        const header = document.createElement("div");
        header.className = "phase-card-header";
        header.onclick = () => togglePhase(phaseCard);

        header.innerHTML = `
          <div class="phase-header-left">
            <span class="phase-month-badge">${phase.duration}</span>
            <span class="phase-title-text">${phase.phaseNumber} · ${phase.title}</span>
          </div>
          <div class="phase-header-right">
            <span class="phase-counter-badge" id="counter_${phase.id}">${phaseChecked}/${phaseTotal}</span>
            <svg class="chevron-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="6 9 12 15 18 9"></polyline>
            </svg>
          </div>
        `;

        // Card Body
        const body = document.createElement("div");
        body.className = "phase-card-body";

        // Sub description
        const subdesc = document.createElement("p");
        subdesc.className = "phase-subdesc";
        subdesc.textContent = phase.description;
        body.appendChild(subdesc);

        // Topics Checklist
        const topicsList = document.createElement("div");
        topicsList.className = "topics-checklist";

        phase.topics.forEach((topicText, topicIndex) => {
          const itemKey = `${roadmap.id}_${phase.id}_${topicIndex}`;
          const isChecked = !!userProgress[itemKey];

          const topicItem = document.createElement("div");
          topicItem.className = `topic-item ${isChecked ? 'checked' : ''}`;
          topicItem.setAttribute("data-topic-key", itemKey);
          topicItem.onclick = (e) => toggleTopic(itemKey, topicItem, phase, roadmap);

          topicItem.innerHTML = `
            <div class="custom-checkbox">
              <svg class="check-svg" viewBox="0 0 24 24">
                <polyline points="20 6 9 17 4 12"></polyline>
              </svg>
            </div>
            <div class="topic-text">${topicText}</div>
          `;
          topicsList.appendChild(topicItem);
        });
        body.appendChild(topicsList);

        // Free Resources Block
        if (phase.resources && phase.resources.length > 0) {
          const resBlock = document.createElement("div");
          resBlock.className = "resources-block";

          let resHtml = `
            <div class="resources-heading">
              <span>Free Curated Resources</span>
              <span style="font-size: 0.7rem; color: var(--accent-gold);">Verified Free</span>
            </div>
            <div class="resource-links-wrap">
          `;

          phase.resources.forEach(r => {
            let icon = "📄";
            let typeClass = "docs";
            if (r.type === "video") {
              icon = "📺 YouTube:";
              typeClass = "video";
            } else if (r.type === "book") {
              icon = "📖 Free Book:";
              typeClass = "book";
            } else if (r.type === "interactive") {
              icon = "💻 Interactive:";
              typeClass = "interactive";
            }

            resHtml += `
              <a href="${r.url}" target="_blank" rel="noopener noreferrer" class="res-link ${typeClass}" title="Open free learning resource in new tab">
                <span class="res-icon">${icon}</span>
                <span>${r.name}</span>
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="opacity: 0.7;">
                  <line x1="7" y1="17" x2="17" y2="7"></line>
                  <polyline points="7 7 17 7 17 17"></polyline>
                </svg>
              </a>
            `;
          });

          resHtml += `</div>`;
          resBlock.innerHTML = resHtml;
          body.appendChild(resBlock);
        }

        phaseCard.appendChild(header);
        phaseCard.appendChild(body);
        container.appendChild(phaseCard);
      });
    }

    // Toggle single phase accordion
    function togglePhase(card) {
      card.classList.toggle("open");
    }

    // Toggle Expand All / Collapse All
    function toggleExpandAll() {
      allExpanded = !allExpanded;
      document.querySelectorAll(".phase-card").forEach(c => {
        if (allExpanded) c.classList.add("open");
        else c.classList.remove("open");
      });
      document.getElementById("expandAllBtnText").textContent = allExpanded ? "Collapse All" : "Expand All";
    }

    // Toggle individual topic checkbox
    function toggleTopic(itemKey, topicElement, phase, roadmap) {
      if (userProgress[itemKey]) {
        delete userProgress[itemKey];
        topicElement.classList.remove("checked");
      } else {
        userProgress[itemKey] = true;
        topicElement.classList.add("checked");
      }
      saveProgress();

      // Update Phase Counter
      let phaseTotal = phase.topics.length;
      let phaseChecked = 0;
      phase.topics.forEach((_, tIdx) => {
        const key = `${roadmap.id}_${phase.id}_${tIdx}`;
        if (userProgress[key]) phaseChecked++;
      });

      const counterBadge = document.getElementById(`counter_${phase.id}`);
      if (counterBadge) {
        counterBadge.textContent = `${phaseChecked}/${phaseTotal}`;
      }

      const phaseCard = document.getElementById(`phase_card_${phase.id}`);
      if (phaseCard) {
        if (phaseChecked === phaseTotal && phaseTotal > 0) {
          phaseCard.classList.add("all-completed");
        } else {
          phaseCard.classList.remove("all-completed");
        }
      }

      updateRoadmapProgress();
      renderTabs();
    }

    // Update Overall Roadmap Progress Bar
    function updateRoadmapProgress() {
      const roadmap = ROADMAPS_DATA[activeRoadmapId];
      if (!roadmap) return;

      let total = 0;
      let done = 0;

      roadmap.phases.forEach(p => {
        p.topics.forEach((_, idx) => {
          total++;
          const itemKey = `${roadmap.id}_${p.id}_${idx}`;
          if (userProgress[itemKey]) done++;
        });
      });

      const percent = total > 0 ? Math.round((done / total) * 100) : 0;

      document.getElementById("progressDoneText").textContent = `${done} / ${total} done`;
      document.getElementById("progressPercentBadge").textContent = `${percent}%`;
      document.getElementById("progressBarFill").style.width = `${percent}%`;
      
      const remaining = total - done;
      document.getElementById("progressRemainingText").textContent = 
        remaining === 0 ? "🎉 Congratulations! You have completed all topics in this roadmap!" : `${remaining} topics remaining`;
    }

    // Reset All Progress for Active Roadmap
    function resetActiveRoadmap() {
      const roadmap = ROADMAPS_DATA[activeRoadmapId];
      if (!confirm(`Are you sure you want to reset all your progress for "${roadmap.title}"?`)) {
        return;
      }

      roadmap.phases.forEach(p => {
        p.topics.forEach((_, idx) => {
          const itemKey = `${roadmap.id}_${p.id}_${idx}`;
          delete userProgress[itemKey];
        });
      });

      saveProgress();
      renderPhases();
      updateRoadmapProgress();
      renderTabs();
    }

    // Initial load
    window.addEventListener("DOMContentLoaded", () => {
      loadProgress();
      renderTabs();
      renderActiveRoadmap();
    });
